CREATE     VIEW [FO].[vwCostCentre]
AS

SELECT tab.*, cc2.Main_Area, cc2.Sub_Area, cc2.Sub_Director, cc2.Director, cc2.Directorate_SubArea, cc2.Directorate
FROM 
	(
		SELECT T1.NAME AS [CostCentre_Name]
			,T1.NAMEALIAS AS NAMEALIAS
			,T1.PARTYNUMBER AS PARTYNUMBER
			,T1.OPERATINGUNITNUMBER AS OPERATINGUNITNUMBER
			,T1.OPERATINGUNITTYPE AS OPERATINGUNITTYPE
			,T1.PARTYTYPE AS PARTYTYPE
			,T1.RECID AS RECID
			,T3.DUNSNUMBERRECID AS DUNSNUMBERRECID
			,T3.HCMWORKER AS HCMWORKER
			,T4.DUNSNUMBER AS DUNSNUMBER
			,T5.PERSONNELNUMBER AS MANAGERPERSONNELNUMBER
			,T6.NAME AS MANAGERNAME
			,T1.OPERATINGUNITNUMBER AS  [CostCentre_Code]
			
		FROM synapse_fo.DIRPARTYBASEENTITY_RICS T1
			CROSS JOIN synapse_fo.DIRPARTYTABLE T3
			LEFT OUTER JOIN synapse_fo.DIRDUNSNUMBER T4 ON (
					(T3.DUNSNUMBERRECID = T4.RECID)
					AND (T3.PARTITION = T4.PARTITION)
					)
			LEFT OUTER JOIN synapse_fo.HCMWORKER T5 ON (
					(T3.HCMWORKER = T5.RECID)
					AND (T3.PARTITION = T5.PARTITION)
					)
			LEFT OUTER JOIN synapse_fo.DIRPARTYTABLE T6 ON (
					(T5.PERSON = T6.RECID)
					AND (T5.PARTITION = T6.PARTITION)
					)
			WHERE (
					(
						(T1.PARTYTYPE = N'OperatingUnit')
						AND (
							(T1.PARTYNUMBER = T3.PARTYNUMBER)
							AND (T1.PARTITION = T3.PARTITION)
							)
						)
					AND T3.INSTANCERELATIONTYPE IN (11000)
					)
	) tab
		LEFT JOIN [Static].[vwCostCentre_Hierarchy] cc2
			on tab.[OPERATINGUNITNUMBER] = cc2.[CostCentreCode]
